from dataclasses import dataclass, field

from .pricing import format_price, line_total


@dataclass
class Item:
    sku: str
    unit_cents: int
    qty: int = 1
    category: str = "general"


@dataclass
class Cart:
    currency: str = "TWD"
    items: list = field(default_factory=list)

    def add(self, sku: str, unit_cents: int, qty: int = 1, category: str = "general") -> None:
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.items.append(Item(sku, unit_cents, qty, category))

    def total_cents(self) -> int:
        return sum(line_total(i.unit_cents, i.qty) for i in self.items)

    def summary(self) -> str:
        return f"{len(self.items)} 項，合計 {format_price(self.total_cents())}"

