from .pricing import format_price, line_total


class Invoice:
    def __init__(self, cart, number: str):
        self.cart = cart
        self.number = number
        self.currency = cart.currency

    def render(self) -> str:
        lines = [f"發票 #{self.number}"]
        for it in self.cart.items:
            lines.append(f"  {it.sku} x{it.qty}  {format_price(line_total(it.unit_cents, it.qty))}")
        lines.append(f"總計 {format_price(self.cart.total_cents())}")
        return "\n".join(lines)

