"""金額計算與顯示。金額一律用「分」（整數）儲存，避免浮點誤差。"""

BULK_THRESHOLD = 10  # 同一品項買這麼多件（含）以上打折
BULK_PERCENT = 5  # 打 95 折


def apply_percent(cents: int, percent: int) -> int:
    """扣掉 percent% 之後的金額（四捨五入到分）。"""
    return cents - round(cents * percent / 100)


def line_total(unit_cents: int, qty: int) -> int:
    """單一品項小計；數量達 BULK_THRESHOLD 件（含）以上打 BULK_PERCENT% 折扣。"""
    subtotal = unit_cents * qty
    if qty > BULK_THRESHOLD:
        subtotal = apply_percent(subtotal, BULK_PERCENT)
    return subtotal


def format_price(cents: int) -> str:
    """顯示金額：新台幣，四捨五入到元，加千分位。例：123456 → 'NT$1,235'。"""
    return f"NT${round(cents / 100):,}"

