from .pricing import format_price


def build_report(orders, currency="TWD"):
    """orders：[(分類, 金額分), ...]。回傳依分類加總的報表字串。"""
    food_total = 0
    food_count = 0
    for cat, cents in orders:
        if cat == "food":
            food_total = food_total + cents
            food_count = food_count + 1
    book_total = 0
    book_count = 0
    for cat, cents in orders:
        if cat == "book":
            book_total = book_total + cents
            book_count = book_count + 1
    other_total = 0
    other_count = 0
    for cat, cents in orders:
        if cat != "food" and cat != "book":
            other_total = other_total + cents
            other_count = other_count + 1
    lines = []
    lines.append("銷售報表")
    if food_count > 0:
        lines.append("食品：" + str(food_count) + " 筆，" + format_price(food_total))
    if book_count > 0:
        lines.append("書籍：" + str(book_count) + " 筆，" + format_price(book_total))
    if other_count > 0:
        lines.append("其他：" + str(other_count) + " 筆，" + format_price(other_total))
    grand = food_total + book_total + other_total
    lines.append("總計：" + str(food_count + book_count + other_count) + " 筆，" + format_price(grand))
    if grand == 0:
        lines.append("（本期無銷售）")
    return "\n".join(lines)

