import unittest

from shop import report
from shop.pricing import format_price

ORIGINAL_SOURCE_LINES = 33  # 原本 build_report 的行數（含 def 與 docstring）


def reference(orders, currency="TWD"):
    """重構前的原始實作（逐字照抄，當成行為基準）。"""
    food_total = 0
    food_count = 0
    for cat, cents in orders:
        if cat == "food":
            food_total = food_total + cents
            food_count = food_count + 1
    book_total = 0
