        if cat == "book":
            book_total = book_total + cents
            book_count = book_count + 1
    other_total = 0
    other_count = 0
    for cat, cents in orders:
        if cat != "food" and cat != "book":
            other_total = other_total + cents
            other_count = other_count + 1
    lines = []
    lines.append("銷售報表")
    if food_count > 0:
        lines.append("食品：" + str(food_count) + " 筆，" + format_price(food_total))
    if book_count > 0:
        lines.append("書籍：" + str(book_count) + " 筆，" + format_price(book_total))
    if other_count > 0:
