    return "\n".join(lines)


CASES = [
    [],
    [("food", 3000)],
    [("book", 1999), ("book", 1)],
    [("toy", 500), ("", 100), ("Food", 700)],
    [("food", 0)],
    [("food", 1000), ("book", -1000)],
    [("other", 250), ("food", 250), ("book", 250), ("misc", 250)],
    [("food", 123456), ("book", 99), ("pen", 50)],
]


class HiddenRefactor(unittest.TestCase):
    def test_same_output_fixed_cases(self):
        for orders in CASES:
            with self.subTest(orders=orders):
                self.assertEqual(report.build_report(list(orders)), reference(list(orders)))

    def test_same_output_random(self):
        rnd = random.Random(20261125)
        cats = ["food", "book", "toy", "other", ""]
        for _ in range(300):
            orders = [(rnd.choice(cats), rnd.randint(-5000, 50000)) for _ in range(rnd.randint(0, 8))]
            self.assertEqual(report.build_report(list(orders)), reference(list(orders)), orders)

    def test_actually_refactored(self):
        src = inspect.getsource(report.build_report)
        self.assertLess(len(src.strip().splitlines()), ORIGINAL_SOURCE_LINES, "build_report 沒有變短")


if __name__ == "__main__":
    unittest.main()
